\par \pard\fi0\li0\tx720\tx5115\tx6525\tx7080\ql\ri0\sb0\sa0\itap0 WZ Ochsenk\u246 \'f6pfe (EBDB DE8100-CodBibl27b_107, DE8100-CodBibl27b_223), Krone\plain \f0\fs16  (\plain \f1\lang1033\fs20 EBDB\plain \f0\fs16  \plain \f1\lang1033\fs20 DE8100-CodBibl27b_13\plain \f2\lang1033\fs20 ), \plain \f1\lang1033\fs20 Geometrische Figur\plain \f0\fs16  (\plain \f1\lang1033\fs20 EBDB DE8100-CodBibl27b_999), alle {\field{\*\fldinst HYPERLINK "hida://5060[0].5064/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 1455-1457}}\plain \f1\lang1033\fs20 . 1\plain \f1\super\lang1033\fs20 I\plain \f1\lang1033\fs20  + 34 VI\plain \f1\super\lang1033\fs20 407\plain \f1\lang1033\fs20  + I\plain \f1\super\lang1033\fs20 409\plain \f1\lang1033\fs20 ; fehlerhafte Z\u228 \'e4hlung \plain \f1\i\lang1033\fs20 327, 327a\plain \f1\lang1033\fs20 ; Reklamanten und Doppelblattz\u228 \'e4hlungen wie in Band 7a, ab 96\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 , die Reklamanten von der Hand des zweiten Schreibers; moderne Foliierung. Textualis von der Hand des {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Theoderich von Alkmaar}}\plain \f1\lang1033\fs20 , ab 109\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  Textualis von einem zweiten Schreiber. }

