\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 Lit.: Kat. 2.1; Marie und Heinz \plain \f1\scaps\lang1033\fs24 Roosen\plain \f1\scaps\lang1033\fs24 \endash \plain \f1\scaps\lang1033\fs24 Runge\plain \f1\lang1033\fs24 : Das sp\u228 \'e4tgotische Musterbuch des Stephan Schriber in der Bayerischen Staatsbibliothek M\u252 \'fcnchen Cod. ikon. 420, Bd. 2, Wiesbaden 1981, S. 143f., 227, 290, Bd. 3, Abb. 173\endash 176 (104\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 , 50\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24 , 165\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

