\par \pard\fi0\li0\ql\ri0\sb120\sa0\itap0 2\u176 \'b0 3a, II\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : 15 Teile; 2\u176 \'b0 3b, 1\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : 22 Teile, 206\plain \f1\super\lang1033\fs20 r\plain \f1\lang1033\fs20  1 Teil; 2\u176 \'b0 3c, III\plain \f1\super\lang1033\fs20 v\plain \f1\lang1033\fs20 : 23 Teile. Aus historisierten Initialen und zahlreichen Bord\u252 \'fcrenst\u252 \'fccken unterschiedlicher Gr\u246 \'f6\u223 \'dfe wurden gro\u223 \'dfformatige Bildseiten mit Bord\u252 \'fcren gebildet. Zu den Tr\u228 \'e4gerb\u228 \'e4nden siehe: Kat. illum. Hss., 3.1, S. 163-168, Kat. Nr. 80-82; Kat. 1.4 (in Vorbereitung)}

