\pard\fi0\li0\tx914\tx1828\tx2742\tx3669\tx4583\tx5497\tx6411\tx7325\tx8239\tx9166\tx10080\tx10994\tx11908\tx12822\tx13736\tx14650\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 Miniaturen
