\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 10\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Guelfo\plain \f1\lang1033\fs24  (Welf I.). In silbernem Harnisch mit Panzerhandschuhen, das Schwert an der linken Seite, in rotem Mantel thronend. Roter {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 F\u252 \'fcrstenhut}}\plain \f1\lang1033\fs24  mit goldenen Borten. Wappen: in blau drei goldene Lilien (vgl. Bildtitel: \u8230 \'85 \plain \f1\i\lang1033\fs24 des \plain \f2\i\lang1024\fs24 bl\u367 \'f9ts von frankreich\plain \f1\lang1033\fs24 ). }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 11\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  Judith, Tochter Welfs, {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Ehefrau}}\plain \f1\lang1033\fs24  Ludwigs des Frommen. B\u252 \'fcgelkrone, in wei\u223 \'dfem Kleid und gr\u252 \'fcnem Mantel, zu Ludwig gewandt stehend, die Linke erhoben. }

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

