\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 20\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  Heinrich, Sohn von Rudolf II. von Altdorf. Nach rechts schreitend, den Kopf zur\u252 \'fcckgewandt. Als jugendlicher {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 J\u228 \'e4ger}}\plain \f1\lang1033\fs24  mit Harnisch und knielangem Gewand mit Beutel\u228 \'e4rmeln. In der Linken einen Jagdspie\u223 \'df, ausger\u252 \'fcstet mit Jagdhorn sowie einer G\u252 \'fcrteltasche mit Dolch. Wappen: in Gold ein steigender roter L\u246 \'f6we.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

