\pard\fi0\li0\tx914\tx1828\tx2742\tx3669\tx4583\tx5497\tx6411\tx7325\tx8239\tx9166\tx10080\tx10994\tx11908\tx12822\tx13736\tx14650\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs20 Hinterer Spiegel: Notizen zu Geldgesch\u228 \'e4ften und {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6922/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Testament}}\plain \f1\lang1033\fs20  von {\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Hans Seyff}}\plain \f1\lang1033\fs20  und seiner Ehefrau {\field{\*\fldinst HYPERLINK "hida://bezper[1].4100/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 Anna Heuler}}\plain \f1\lang1033\fs20 .}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset0 Courier New;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

