\par \pard\fi0\li0\ql\ri0\sb125\sa0\itap0 2\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  zum Beginn des Temporale (\plain \f1\i\lang1033\fs24 Ecce nomen domini\plain \f1\lang1033\fs24 \u8230 \'85\~): {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Augustus und die Sibylle}}\plain \f1\lang1033\fs24 , Teilbord\u252 \'fcre: oben und rechts B\u252 \'fcten- und Fruchtranken mit Figuren (Schmetterling, Schneckenhaus, Katze, J\u228 \'e4ger, Fuchs, Hirsch, L\u246 \'f6we, Lastentr\u228 \'e4ger), unten Szene: zwei Bediente mit Grill, Topf, Wurst und Weinschlauch sowie Spruchb\u228 \'e4nder (links: \plain \f1\i\lang1033\fs24 non estimo sapientem ignotis illudentem: l\u246 \'f6schst du mir den turst, so gib ich dir a die wurst\plain \f1\lang1033\fs24  [vgl. Sebastian \plain \f1\scaps\lang1033\fs24 Brant\plain \f1\lang1033\fs24 : Das Narrenschiff, hrsg. von Manfred \plain \f1\scaps\lang1033\fs24 Lemmer\plain \f1\lang1033\fs24 , 3. Aufl. T\u252 \'fcbingen 1986, S. 211, Kap. 81, Z. 53f.]; rechts: \plain \f1\i\lang1033\fs24 vinum bonum et suave, perso\plain \f1\lang1033\fs24 [l]\plain \f1\i\lang1033\fs24 vemus illud ave etc.\plain \f1\lang1033\fs24  [vgl. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 AH 54, Nr. 218}}\plain \f1\lang1033\fs24 ]). }

