\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 248\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  zum Verk\u252 \'fcndigungsfest (\plain \f1\i\lang1033\fs24 Spiritus sanctus in te\plain \f1\lang1033\fs24 \u8230 \'85\~): {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Maria}}\plain \f1\lang1033\fs24  am Betpult, \u252 \'fcber ihr die Taube des Hl. Geistes, links der herabschwebende Engel, Teilbord\u252 \'fcre rechts mit Blattranken und Bl\u252 \'fcten.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 253\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  zur Inventio sancte crucis (\plain \f1\i\lang1033\fs24 O crux splendidior\plain \f1\lang1033\fs24 \u8230 \'85 ): Altarkreuz, am linken Seitenrand, die Hll. {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Helena}}\plain \f1\lang1033\fs24  (Krone, Szepter, Kreuz), darunter ein heiliger Papst mit dreifachem Kreuzstab, darunter ein kniender Benediktiner mit Wappen (in Blau ein Fleischerbeil auf rotem Dreiberg, Buchstaben \plain \f1\i\lang1033\fs24 A. E.\plain \f1\lang1033\fs24 , m\u246 \'f6glicherweise als Alpha und Omega zu deuten, vgl. die Initiale {\field{\*\fldinst HYPERLINK "hida://5007[0].501m/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Cod. mus. 2\u176 \'b0 I 65}}\plain \f1\lang1033\fs24 , 137\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  mit dem Wappen Leonhard Wagners sowie 186\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24 ), Blattranken.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 256\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  zur Vigil Johannes des T\u228 \'e4ufers (\plain \f1\i\lang1033\fs24 Ipse preibit ante\plain \f1\lang1033\fs24 \u8230 \'85\~): {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Johannes der T\u228 \'e4ufer}}\plain \f1\lang1033\fs24  segnend, vor ihm am Boden ein Buch darauf das Lamm Gottes, Blattranke und Bl\u252 \'fcten.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 261\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  zu St. Peter und Paul (\plain \f1\i\lang1033\fs24 Tu es pastor\plain \f1\lang1033\fs24 \u8230 \'85\~): im Vordergrund {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Kreuzigung des Petrus}}\plain \f1\lang1033\fs24 , im Hintergrund Enthauptung des Paulus, Teilbord\u252 \'fcre, links Blattranke, rechts Bl\u252 \'fctenstengel, Hirsche, Wappen (in Rot eine Sense) und Blattranke.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 269\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  zur Heimsuchung Mariens (\plain \f1\i\lang1033\fs24 In splendoribus sanctorum\plain \f1\lang1033\fs24 \u8230 \'85\~): {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Maria}}\plain \f1\lang1033\fs24  mit Joseph und Elisabeth von einer Magd begleitet, Teilbord\u252 \'fcre, links Blattranke rechts Blattranken mit Wappenschild (in Blau ein silberner L\u246 \'f6we).}

