\uc1
\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 282\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  zum Fest der Hl. Afra (\plain \f1\i\lang1033\fs24 Gloriosa et beatissima\plain \f1\lang1033\fs24 \u8230 \'85\~; vgl. Walter \plain \f1\scaps\lang1033\fs24 Berschin\plain \f1\lang1033\fs24 : Historia S. Konradi, in: Der Heilige Konrad, Bischof von Konstanz, Freiburg 1975, S. 107-128, S. 114f.): die {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Heilige}}\plain \f1\lang1033\fs24  gekr\u246 \'f6nt an einen kahlen Baumstamm gefesselt und im Feuer stehend, Teilbord\u252 \'fcre rechts mit Blumenranken und Wappenschild (Herren von Gaisberg: in Gold ein braunes Bockshorn, vgl. \plain \f1\scaps\lang1033\fs24 Alberti\plain \f1\lang1033\fs24  1, S. 212).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 286\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  zum Fest des Hl. Laurentius (\plain \f1\i\lang1033\fs24 Levita Laurentius\plain \f1\lang1033\fs24 \u8230 \'85\~): {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Martyrium}}\plain \f1\lang1033\fs24  auf einem Rost \u252 \'fcber gl\u252 \'fchenden Kohlen, dahinter vier M\u228 \'e4nner, die das Feuer anfachen, Teilbord\u252 \'fcre links mit Blattranken, oben ein Wappen (Herren von Schechingen: geteilt, oben gespalten von Rot und Wei\u223 \'df, unten Blau \endash  1443\endash 1461 war Volkart von Schechingen Abt von Lorch). In der dritten Textzeile Schmetterlinge, mittig ein Segelfalter (Iphiclides podalirius).}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 290\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  zu Mari\u228 \'e4 Himmelfahrt (\plain \f1\i\lang1033\fs24 Virgo prudentissima\plain \f1\lang1033\fs24 \u8230 \'85\~): {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Marientod}}\plain \f1\lang1033\fs24 , im Vordergrund Petrus und Johannes st\u252 \'fctzen die kniend betende Maria vor Bett und Betpult, dahinter weitere J\u252 \'fcnger, oben rechts die kniende Maria vor Christus im Himmel, Teilbord\u252 \'fcre, links vier kniende Lorcher \u196 \'c4bte in ihrem Ornat mit Wappen: Nikolaus Schenk von Arberg (1462-1477), Jodocus Winkelhofer (1477-1480), Georg Kerler (1481-1510), Sebastian Sitterich (1510-1525), unten Blattranken, mittig das Wappen des Klosters Lorch.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}{\f2\fnil\fcharset238 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;}

\uc1
\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 296\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  zur Geburt Marias (\plain \f1\i\lang1033\fs24 Gloriose virginis Marie\plain \f1\lang1033\fs24 \u8230 \'85\~): die Hl. {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Anna}}\plain \f1\lang1033\fs24  in einem Bett mit S\u228 \'e4ugling, Teilbord\u252 \'fcre links Blattranken, unten Wappen des Thomas K\u246 \'f6llin, Pfarrer zu Lorch (geteilt von Blau und Gold, oben ein, unten zwei Sterne in der Gegenfarbe). Zu K\u246 \'f6llin: \plain \f1\scaps\lang1033\fs24 Graf\plain \f1\lang1033\fs24  1990, S. 91f.}

