\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 Historisierte Initialen
\par \pard\fi0\li0\ql\ri0\sb125\sa0\itap0 1\plain \f1\super\lang1033\fs24 r\plain \f1\lang1033\fs24  zum Beginn des Graduale (\plain \f1\i\lang1033\fs24 Ad te levavi animam\plain \f1\lang1033\fs24 \u8230 \'85\~): Weltgericht mit thronendem Christus, Maria und Johannes d.T. ({\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Deesis}}\plain \f1\lang1033\fs24 ) sowie auferstehenden M\u246 \'f6nchen, Streublumenbord\u252 \'fcre an drei Seiten: oben Blumen, V\u246 \'f6gel (u.a. Nebelkr\u228 \'e4hen) und Putten; rechts Halbfiguren in Bl\u252 \'fctenkelchen, dazwischen Blumen und Fr\u252 \'fcchte, von oben: Bischof mit Spruchband (\plain \f1\i\lang1033\fs24 Sanct Wernherus\plain \f1\lang1033\fs24 ), Sebastian mit Bogen und Pfeil, Wappen des Abtes Sebastian Sitterich, Hl. Barbara (Kelch mit Schlange, M\u228 \'e4rtyrerpalme?), Hl. Anna selbdritt, Hl. Katharina; unten: mittig das Wappen des Reiches (in Gold schwarzer Doppeladler, bekr\u246 \'f6nt mit B\u252 \'fcgelkrone), links davon Herzog Ulrich von W\u252 \'fcrttemberg mit Wappen und Spruchband (\plain \f1\i\lang1033\fs24 Udalricus dux de wirteberg et\plain \f1\lang1033\fs24  [Rest getilgt]), hinter ihm zwei kniend betende M\u228 \'e4nner, rechts Herzogin Sabina von Bayern (\plain \f1\i\lang1033\fs24 Sabina ducissa bavarie uxor eius\plain \f1\lang1033\fs24 ), seine Frau, hinter ihr zwei kniend betende Frauen.}

{\rtf1\ansi\ansicpg0\uc1\deff0\deflang0\deflangfe0{\fonttbl{\f0\fnil\fcharset1 Arial;}{\f1\fnil\fcharset0 Times New Roman;}}{\colortbl;\red0\green0\blue0;\red0\green0\blue255;\red0\green255\blue255;\red0\green255\blue0;\red255\green0\blue255;\red255\green0\blue0;\red255\green255\blue0;\red255\green255\blue255;\red0\green0\blue128;\red0\green128\blue128;\red0\green128\blue0;\red128\green0\blue128;\red128\green0\blue0;\red128\green128\blue0;\red128\green128\blue128;\red192\green192\blue192;\red204\green238\blue221;\red224\green224\blue224;}

\uc1
\pard\fi0\li0\ql\ri0\sb125\sa0\itap0 \plain \f1\lang1033\fs24 13\plain \f1\super\lang1033\fs24 v\plain \f1\lang1033\fs24  zur Weihnachtsmesse (\plain \f1\i\lang1033\fs24 Puer natus est\plain \f1\lang1033\fs24 \u8230 \'85\~): {\field{\*\fldinst HYPERLINK "hida://5500[0]/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17 Geburt Christi}}\plain \f1\lang1033\fs24 , das Kind liegt auf einem Zipfel des Marienmantels auf dem Boden, im Hintergrund Verk\u252 \'fcndigung an die Hirten, Teilbord\u252 \'fcre, oben: Putten mit Spruchb\u228 \'e4ndern und Notenblatt mit Versen aus dem \u8222 \'84Gloria\ldblquote : \plain \f1\i\lang1033\fs24 Gratiam agimus\u8230 \'85 , Gloria in excelsis\u8230 \'85 \plain \f1\lang1033\fs24 , \plain \f1\i\lang1033\fs24 Quoniam tu solus sanctus\u8230 \'85 \plain \f1\lang1033\fs24 ; links und unten: acht m\u228 \'e4nnliche Halbfiguren mit Schriftb\u228 \'e4ndern (Text bei \plain \f1\scaps\lang1033\fs24 Gottwald\plain \f1\lang1033\fs24  1964, S. 123), auf dem letzten signiert \plain \f1\i\lang1033\fs24 1512 NB\plain \f1\lang1033\fs24  (Nikolaus Bertschi). }

