\par \pard\fi0\li0\tx720\tx5115\tx6525\tx7080\ql\ri0\sb0\sa0\itap0 WZ 2 Ochsenk\u246 \'f6pfe, Ravensburg, dat. 1446 und 1448 (Aufzeichnungen Piccard). 4 VI\plain \f1\super\lang1033\fs20 48\plain \f1\lang1033\fs20  + (VII-1)\plain \f1\super\lang1033\fs20 61\plain \f1\lang1033\fs20  + 8 VI\plain \f1\super\lang1033\fs20 157\plain \f1\lang1033\fs20  + (V-1)\plain \f1\super\lang1033\fs20 166\plain \f1\lang1033\fs20 ; Lagenz\u228 \'e4hlung \plain \f1\i\lang1033\fs20 primus, secundus\plain \f1\lang1033\fs20  \u8230 \'85, arabische Doppelblattz\u228 \'e4hlung, moderne Foliierung. Schriftraum 24-25 x 13,5-14; 2-spaltig; 35-40 Zeilen. Bastarda, eine Hand; 2-zeilige, rote Abschnittsinitialen, viele nicht ausgef\u252 \'fchrt. Rubriziert. Schreibsprache {\field{\*\fldinst HYPERLINK "hida://5710[0]/?u"}{\fldrslt \plain \f1\lang1033\fs20\chcbpat17 schw\u228 \'e4bisch}}\plain \f1\lang1033\fs20 .}

