\pard\sl360\slmult1\fi0\li0\ql\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24 1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -189\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24  <{\field{\*\fldinst HYPERLINK "hida://bezper[0].4100/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Petrus Lombardus}}\plain \f1\scaps\lang1033\fs24  : {\field{\*\fldinst HYPERLINK "hida://bezwrk[0].6930/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Glossatura maior super Psalterium}}\plain \f1\lang1033\fs24 >. (1\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -2\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 ) Praefatio; (2\plain \f1\super\lang1033\fs24 rb\plain \f1\lang1033\fs24 -5\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) Ps 1,1-4,6 ...\plain \f1\i\lang1033\fs24  spiritu sancto succensa ut\plain \f1\lang1033\fs24 //, PL 191 Sp. 55-87C; (6\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -67\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) f\u228 \'e4hrt fort ... <no>\plain \f1\i\lang1033\fs24 men tuum, quoniam tu benedices iusto\plain \f1\lang1033\fs24  ...-...\plain \f1\i\lang1033\fs24  et David postea fuit etiam in adver\plain \f1\lang1033\fs24 <sis>//, Ps 5,14-50,11, PL 191 Sp. 101C-490A; (68\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -143\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) ... \plain \f1\i\lang1033\fs24 Non deserit malum ...-...\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Adiuva me domine deus meus\plain \f1\lang1033\fs24 //, Ps 51,3-108,25, PL 191 Sp. 497A-995D; (144\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -144\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) ... \plain \f1\i\lang1033\fs24 capita in terra multorum ...-... Itum est enim ad gentes, mul\plain \f1\lang1033\fs24 <ti>//,\plain \f1\i\lang1033\fs24  \plain \f1\lang1033\fs24 Ps 109,7-110,10, PL 191 Sp. 1001D-1009D; (145\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 - ) ...\plain \f1\i\lang1033\fs24  A solis ortu ...-... in quem non crediderunt? Dum\plain \f1\lang1033\fs24 //, Ps 112,3-114,2, PL 191 Sp. 1016A-1027B; (147\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -168\plain \f1\super\lang1033\fs24 vb\plain \f1\lang1033\fs24 ) ... \plain \f1\i\lang1033\fs24 ut sit in unum omnium redacta ...-...\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 De quo non implebit manum suam\plain \f1\lang1033\fs24 //, Ps 116,1-128,6, PL 191 Sp. 1033A-1166C; (169\plain \f1\super\lang1033\fs24 ra\plain \f1\lang1033\fs24 -189\plain \f1\super\lang1033\fs24 va\plain \f1\lang1033\fs24 ) ... \plain \f1\i\lang1033\fs24 manibus ecclesie ut crescant ...-...\plain \f1\lang1033\fs24  \plain \f1\i\lang1033\fs24 Omnis spiritus laudet dominum. \plain \f1\lang1033\fs24 Anschlie\u223 \'dfend Schreibervers\plain \f1\i\lang1033\fs24  Finito Christus rex libro sit benedictus\plain \f1\lang1033\fs24 . Ps 130,4-150,5, PL 191 Sp. 1173A-1296B. {\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\scaps\lang1033\fs24\chcbpat17 Stegm\u252 \'fcller}}{\field{\*\fldinst HYPERLINK "hida://bezlit[0].8330/?u"}{\fldrslt \plain \f1\lang1033\fs24\chcbpat17  4 Nr. 6637}}\plain \f1\lang1033\fs24 .
